type GrammarParserBootstrap struct {
	input []byte
	vm    *virtualMachine
}

func NewGrammarParserBootstrap() *GrammarParserBootstrap {
	vm := NewVirtualMachine(bytecodeForGrammarParserBootstrap)
	return &GrammarParserBootstrap{vm: vm}
}
func (p *GrammarParserBootstrap) ParseGrammar() (Tree, error)               { return p.parseFn(5) }
func (p *GrammarParserBootstrap) ParseExpression() (Tree, error)            { return p.parseFn(1095) }
func (p *GrammarParserBootstrap) ParseSequence() (Tree, error)              { return p.parseFn(1288) }
func (p *GrammarParserBootstrap) ParsePrefix() (Tree, error)                { return p.parseFn(1356) }
func (p *GrammarParserBootstrap) ParseLabeled() (Tree, error)               { return p.parseFn(1483) }
func (p *GrammarParserBootstrap) ParseSuffix() (Tree, error)                { return p.parseFn(1584) }
func (p *GrammarParserBootstrap) ParsePrimary() (Tree, error)               { return p.parseFn(1820) }
func (p *GrammarParserBootstrap) ParseList() (Tree, error)                  { return p.parseFn(2807) }
func (p *GrammarParserBootstrap) ParseMissingClosingParen() (Tree, error)   { return p.parseFn(3062) }
func (p *GrammarParserBootstrap) ParseMissingClosingCurly() (Tree, error)   { return p.parseFn(3067) }
func (p *GrammarParserBootstrap) ParseMissingClosingBracket() (Tree, error) { return p.parseFn(3072) }
func (p *GrammarParserBootstrap) ParseMissingClosingSQuote() (Tree, error)  { return p.parseFn(3077) }
func (p *GrammarParserBootstrap) ParseMissingClosingDQuote() (Tree, error)  { return p.parseFn(3082) }
func (p *GrammarParserBootstrap) ParseMissingLabel() (Tree, error)          { return p.parseFn(3087) }
func (p *GrammarParserBootstrap) ParseMissingUnicodeOpen() (Tree, error)    { return p.parseFn(3107) }
func (p *GrammarParserBootstrap) ParseMissingUnicodeDigits() (Tree, error)  { return p.parseFn(3112) }
func (p *GrammarParserBootstrap) ParseMissingUnicodeClose() (Tree, error)   { return p.parseFn(3117) }
func (p *GrammarParserBootstrap) ParseMissingImportName() (Tree, error)     { return p.parseFn(3122) }
func (p *GrammarParserBootstrap) ParseMissingImportFrom() (Tree, error)     { return p.parseFn(3358) }
func (p *GrammarParserBootstrap) ParseMissingImportSrc() (Tree, error)      { return p.parseFn(3576) }
func (p *GrammarParserBootstrap) Parse() (Tree, error)                      { return p.parseFn(5) }
func (p *GrammarParserBootstrap) SetInput(input []byte)                     { p.input = input }
func (p *GrammarParserBootstrap) GetInput() []byte                          { return p.input }
func (p *GrammarParserBootstrap) SetLabelMessages(el map[int]int)           { p.vm.SetLabelMessages(el) }
func (p *GrammarParserBootstrap) SetShowFails(v bool)                       { p.vm.SetShowFails(v) }

func (p *GrammarParserBootstrap) parseFn(addr int) (Tree, error) {
	val, _, err := p.vm.MatchRule(p.input, addr)
	return val, err
}
